# Generated by build.py from recipe.yml for recipe http-exchange-a-password-for-a-token. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site site/api plain
printf '%s\n' 'tok-7f3a9c' > site/token.txt
printf '%s\n' '[{"id":1,"total":40}]' > site/api/orders.json
printf '%s\n' 'tok-7f3a9c' > plain/token.txt
cat > login-then-call.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# The client's flow: log in with Basic to fetch a token, then call the API with it as a
# Bearer token. Usage: sh login-then-call.sh <base URL> <user:password>
base=$1
token=$(curl -sSf --cacert server.pem -u "$2" "${base}token.txt") || exit $?
curl -sSf --cacert server.pem --oauth2-bearer "$token" "${base}api/orders.json"
EOF
openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"
surl -v --log-file surl.log --directory site --cert server.pem --key server.key --user app:s3cret --user :tok-7f3a9c https://127.0.0.1:8080/ &
sleep 1
sh login-then-call.sh https://127.0.0.1:8080/ app:s3cret
kill $(jobs -p)
